fn test_prime(candidate: u64) -> bool {
    if candidate <= 1 {
        return false; // Not applicable as per problem statement
    }
    if candidate <= 3 {
        return true; // 2 and 3 are prime
    }
    if candidate % 2 == 0 {
        return false; // Exclude even numbers greater than 2
    }

    let limit = (candidate as f64).sqrt() as u64;
    for i in (3..=limit).step_by(2) {
        if candidate % i == 0 {
            return false; // Found a divisor, not prime
        }
    }
    true // No divisors found, it is prime
}